<?php
declare(strict_types=1);
require dirname(__DIR__).'/autoload.php';
use Wcp360\Sdk\Pairing\{Wire,Client,Transport,CurlTransport,PairingException};
$checks=[];$report=['status'=>'failed'];$check=static function(bool $ok,string $name)use(&$checks):void{if(!$ok)throw new RuntimeException('FAILED: '.$name);$checks[]=$name;};$deny=static function(callable $fn,string $name)use($check):void{try{$fn();throw new RuntimeException('Missing rejection');}catch(PairingException){$check(true,$name);}};
try{
    $key=sodium_crypto_sign_secretkey(sodium_crypto_sign_seed_keypair(str_repeat("\x01",32)));$code='wcp-pair1.'.str_repeat('a',32).'.'.str_repeat('b',64);$r=Wire::request('claim','https://hub.example.test',$key,['code'=>$code,'core_version'=>'1.0.0','os'=>'unknown','architecture'=>'unknown']);$check(sodium_crypto_sign_verify_detached(hex2bin($r['signature']),Wire::bytes('claim',$r),hex2bin($r['public_key'])),'actual signature verifies with public key');
