    $t=new class implements Transport{public array $reply=[];public function post(string $url,array $request):array{return $this->reply;}};$c=new Client($t);$reply=static fn(array $data):array=>['status'=>200,'headers'=>['content-type'=>'application/json','cache-control'=>'private, no-store'],'body'=>json_encode(['data'=>$data],JSON_THROW_ON_ERROR)];$t->reply=$reply($d);$check($c->send('claim',$r)===$d,'exact nonce and public-key-bound receipt accepted');
    foreach(['protocol'=>'other-purpose','audience'=>'https://evil.example.test','public_key_sha256'=>str_repeat('0',64),'request_nonce'=>str_repeat('0',64),'instance_id'=>'../instance','status'=>'revoked','replayed'=>'false','paired_at'=>[]] as $field=>$value){$tampered=$d;$tampered[$field]=$value;$t->reply=$reply($tampered);$deny(fn()=>$c->send('claim',$r),'receipt rejects wrong '.$field);}
    $t->reply=$reply($d+['owner'=>'private-owner']);$deny(fn()=>$c->send('claim',$r),'extra receipt fields refused');$t->reply=$reply($d);$t->reply['headers']['cache-control']='public, max-age=60';$deny(fn()=>$c->send('claim',$r),'cacheable receipt refused');$t->reply=$reply($d);$t->reply['headers']['content-type']='text/html';$deny(fn()=>$c->send('claim',$r),'non-JSON receipt refused');$t->reply=$reply($d);$t->reply['body']=str_repeat('x',16385);$deny(fn()=>$c->send('claim',$r),'oversized receipt refused');$t->reply=['status'=>429,'headers'=>[],'body'=>'DO_NOT_DISCLOSE_UPSTREAM'];try{$c->send('claim',$r);$check(false,'429 must fail');}catch(PairingException $e){$check($e->httpStatus===429&&$e->errorCode==='rate_limited'&&!str_contains($e->getMessage(),'UPSTREAM'),'rate limit stable error without upstream disclosure');}
    $bad=$d;$bad['paired_at']='2026-02-30T00:00:00Z';$t->reply=$reply($bad);$deny(fn()=>$c->send('claim',$r),'invalid calendar timestamp refused');$t->reply=$reply($d);$t->reply['body']=str_replace('"status":"paired"','"status":"revoked","status":"paired"',$t->reply['body']);$deny(fn()=>$c->send('claim',$r),'ambiguous duplicate receipt key refused');
    foreach(['http://example.test','https://user@example.test','https://hub.example.test/a?code=x','https://hub.example.test/a#x','https://hub.example.test/%2f','https://hub.example.test/a/../b'] as $base)$deny(fn()=>Wire::base($base,true),'unsafe origin refused');
    $check(Wire::base('http://127.0.0.1:9283/test',true)==='http://127.0.0.1:9283/test','explicit loopback profile accepted');$deny(fn()=>Wire::base('http://127.0.0.1:9283/test'),'loopback HTTP never enabled implicitly');
    if(isset($argv[1])){
        if($argv[1]!=='http://127.0.0.1:9283')throw new RuntimeException('Private fixture origin required');$curl=new CurlTransport(true);
