        $out=$curl->post($argv[1].'/ok/api/v1/verify-license/pairing/claim',['fixture'=>'synthetic']);$body=json_decode($out['body'],true,8,JSON_THROW_ON_ERROR);$check($out['status']===200&&$body['cookie']===false&&$body['authorization']===false,'real cURL carries no cookie or admin authorization');
    }
