}catch(Throwable $e){$report['failure']=get_class($e).': '.$e->getMessage();}
$report['checks']=count($checks);$report['passed_checks']=$checks;$report['php']=PHP_VERSION;echo json_encode($report,JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR).PHP_EOL;exit($report['status']==='passed'?0:1);
